import{_ as a,o as r,c as n,ag as p}from"./chunks/framework.DzGOF12C.js";const g=JSON.parse('{"title":"basic knowledge","description":"","frontmatter":{},"headers":[{"level":2,"title":"칩안은?","slug":"칩안은","link":"#칩안은","children":[]},{"level":2,"title":"Read, write","slug":"read-write","link":"#read-write","children":[]},{"level":2,"title":"Page","slug":"page","link":"#page","children":[{"level":3,"title":"erase는 block 단위","slug":"erase는-block-단위","link":"#erase는-block-단위","children":[]}]}],"relativePath":"computer/Research/URA/daily/260720 온라인.md","filePath":"computer/Research/URA/daily/260720 온라인.md"}'),s={name:"computer/Research/URA/daily/260720 온라인.md"};function l(t,e,i,o,c,b){return r(),n("div",null,[...e[0]||(e[0]=[p(`<p>메모리를 주로.<br> main, sec<br> sec - HDD, SSD</p><p>SSD 시뮬, 에뮬이 메인</p><p>워게임..? -&gt; 살짝 정체.</p><h1 id="basic-knowledge" tabindex="-1">basic knowledge <a class="header-anchor" href="#basic-knowledge" aria-label="Permalink to &quot;basic knowledge&quot;">​</a></h1><p>저장장치</p><p>NAND기반.<br> 불휘발성 메모리</p><p>어떻게 작동 하는가?<br> 내부 구조</p><p>![[RiF_SSD_structure.png|382]]</p><p><strong>1. 물리적 구조 (실제 칩 안 구조)</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Channel (채널)</span></span>
<span class="line"><span>  └─ LUN (=Die, 칩 하나)</span></span>
<span class="line"><span>       └─ Plane (플레인)</span></span>
<span class="line"><span>            └─ Block (블록)</span></span>
<span class="line"><span>                 └─ Page (페이지) ← 실제 데이터 최소 저장 단위</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>각 단계가 뭔지 (한 번 더 압축해서)</strong></p><ul><li><strong>Channel</strong>: 컨트롤러와 칩들을 잇는 통로(도로)</li><li><strong>LUN</strong>: 그 통로에 연결된 독립 칩 하나 (병렬로 동작 가능)</li><li><strong>Plane</strong>: 칩 안의 구역</li><li><strong>Block</strong>: 지우기(erase)의 최소 단위</li><li><strong>Page</strong>: 쓰기(write)의 최소 단위 (Block 안에 여러 Page)</li></ul><p><strong>2. &quot;Line&quot;이 뭔지 — 이게 핵심</strong></p><p>Line은 물리적 구조가 아니라, <strong>여러 채널·LUN에 걸쳐서 &quot;동시에 함께 쓰이고, 함께 지워지는 블록들의 묶음&quot;</strong>을 관리 편의상 부르는 논리적 단위야.</p><p><strong>왜 이렇게 묶어서 관리하는지</strong></p><p>채널이 8개, LUN이 2개면 총 16개의 병렬 유닛이 있잖아. SSD는 속도를 위해 <strong>이 16개에 동시에 걸쳐서 데이터를 쓰는 게</strong> 효율적</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Line 1 = [채널0-LUN0의 블록3] + [채널0-LUN1의 블록3] + [채널1-LUN0의 블록3] + ... (16개 블록 묶음)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Line</strong>: 여러 채널·LUN에 흩어진 블록들을, 관리상 하나의 단위로 묶어서 부르는 이름.<br> GC도 Line 단위로 진행 — Line 하나를 통째로 정리(valid 복사 + 지우기)</p><p><strong>3. 우리가 실습한 1채널×1LUN에서는 왜 &quot;Line = Block&quot;이 되는지</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>채널이 8개일 때: Line = 8개 채널의 블록들을 묶음 (16개, LUN까지 곱하면)</span></span>
<span class="line"><span>채널이 1개, LUN이 1개일 때: 묶을 대상이 하나뿐 → Line = 그냥 블록 1개 그 자체</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>병렬로 걸칠 다른 채널/LUN이 없으니까, &quot;여러 개를 묶는다&quot;는 Line의 원래 의미가 무색해지고, <strong>Line 하나 = Block 하나</strong>로 단순하게 대응</p><p>ssd 있으면<br> 안의 controller에 NAND 칩여러개가 매달려 있음<br> ![[NAND_channel_way_structure.png|494]]</p><p>2ch, 4way</p><p>way 마다 chip이 있다</p><h2 id="칩안은" tabindex="-1">칩안은? <a class="header-anchor" href="#칩안은" aria-label="Permalink to &quot;칩안은?&quot;">​</a></h2><p>plane이 있고 그 plane을 감싸는 주변회로가 있음</p><p>How to implement<br> 물리적 위치를 좌표로 표현할 수 있음<br> 물리적 위치는 0, 1의 값을 지님</p><p>세로선을 bit line<br> 가로선을 word line</p><p>서로 겹치는 부분이 셀 - cell은 0, 1을 저장. 최소한의 저장 단위<br> cell의 구조가 일반적 메모리와 다름</p><p>DRAM의 경우<br> 커페시터에 저장을 했다가? gate가 있을때 요구하는 전압이 있겠죠<br> 특정 전압보다 높아지면 open<br> 커페시터에 있는 데이터가 점점 leak</p><p>NAND cell의 경우</p><p>일반 트렌지스터와 비교했을 때<br> charge trap layer가 있음 (전하를 붙잡아두는 층)</p><p>기본적으로 트랜지스터를 표현할 때<br> ![[Floating_gate_basic.png]]<br> 밑에 전자가 차서 흐름<br> 전압이 인가되면서 저항이 달라짐</p><p>NAND cell은?<br> ![[Floating_gate_trap_layer.png]]<br> trap layer에 전자를 저장해둘수 있음<br> 전자가 모여야 채널이 열려서 흐른다<br> 트랩레이어에 많으면 밑에 잘 못 붙겠지 -&gt; 저항이 높음</p><p>![[Threshold_voltage_arrow_diagram.png]]<br> 전자를 조절하면 저항이 달라진다 -&gt; 저항을 좀 더 유동적으로 조절 할 수 있음<br> 이건 cell 단위로 행해짐. Vth (문턱전압)을 바꿈</p><h2 id="read-write" tabindex="-1">Read, write <a class="header-anchor" href="#read-write" aria-label="Permalink to &quot;Read, write&quot;">​</a></h2><p>flash에서 데이터를 쓸 때는</p><p>![[Threshold_voltage_distribution_program.png|492]]</p><p>0을 저장하는 cell은 대략 전압 분포가 이 정도 더라</p><p>가운데는 뭐야 그럼<br> Vref -&gt; reference (참조)<br> cell의 상태를 어떻게 구분 할거냐?<br> 가장 편하게 생각할 수 있는 거는 ? 선을 그어서 이 전압을 기준으로<br> 전압을 cell에 인가를 했을 때 흐르면 1 아니면 0</p><p>읽을 때는 Vref를 기준으로!, page 단위로!<br> 쓰는건 word라인에 전압을 인가해서 쓴다.</p><h2 id="page" tabindex="-1">Page <a class="header-anchor" href="#page" aria-label="Permalink to &quot;Page&quot;">​</a></h2><p>Read, write의 기본 단위<br> 그리드 모양<br> ![[NAND_array_page_structure.png|424]]<br> 크로스 되는 부분이 cell<br> 한 덩어리가 page</p><p>wordline에 NAND가 연결<br> page에 해당하는 wordline에 전압을 인가해서 Vth를 바꿈<br> (wordline에 연결된게 많은데 개별적으로 어떻게 바꾸는거지?)</p><h3 id="erase는-block-단위" tabindex="-1">erase는 block 단위 <a class="header-anchor" href="#erase는-block-단위" aria-label="Permalink to &quot;erase는 block 단위&quot;">​</a></h3><p>block안에 page가 많다!<br> 0번째 page에 있는 data가 update가 됐다고 가정.</p><p>![[OS_FS_block_update_diagram.png]]<br> OS에서? FS이 관리를 해줌<br> 안에 블럭들이 해서 여러개가 쫙 있는데?<br> update가 되면 그 자리에 갱신</p><p>HDD에서도 overwrite가 지원. (위와 같은 느낌)</p><p>근데 SSD는 그렇지 못함. (왜 못하지?)<br> 다음공간에 새로 쓰고 기존 값을 invaild로 표시해둠</p><p>(여러 블록을 모으면 plane)<br> ![[Block_valid_invalid_free_pages.png]]<br> update가 잦다면?<br> free page가 점점 줄어들고 block이 가득 차겠죠..</p><p>그러면 빨간게 아닌 것만 추려내서 새로운 page에 옮김<br> 그리고 기존 page를 지워. GC에서 erase를 씀 (GC garbage collection)</p><p>과제 없음!</p><p>nvmeVirt<br> 서울대에서 만든 에뮬</p><p>구체적 사용법 다음시간에 알려줌<br> 다음시간에 뜯어보라고 과제 줄 예정<br> conv ftl이걸 뜯어 보기</p><p>repo 다운 받고 한번 보기</p>`,55)])])}const u=a(s,[["render",l]]);export{g as __pageData,u as default};
